"""Root-owned review envelope; reuses supervisor-save-root full-row digest/guard design.
Never connects to DB. Capture via read-only capture.sql, then compose offline.
"""
import json,re,hashlib,argparse
from pathlib import Path
ROOT=Path(__file__).resolve().parent
CHANGED=['private.refresh_automatic_invoice(uuid,uuid,date)','private.refresh_automatic_payment_certificate(uuid,uuid,date)','private.certificate_calculation_rows(uuid,uuid,date,date)','private.expense_payment_v2_guard()']
TABLES=['public.invoices','public.payment_certificates','public.invoice_approvals','public.invoice_detail_lines','public.attendance_entries','public.daily_reports','public.daily_report_workers','public.payroll_statements','public.companies','public.company_members','public.customers','public.partner_companies']
INPUT=ROOT/'product-input.sql.review-only'
PUBLIC_API=[]
for name,args in re.findall(r'create function public\.([a-z_0-9]+)\((.*?)\)\s*returns',INPUT.read_text(),re.S|re.I):
 types=[x.strip().split()[1]for x in args.split(',')if x.strip()]
 PUBLIC_API.append('public.'+name+'('+','.join(types)+')')

def lit(x):return "'"+x.replace("'","''")+"'"
def jl(x):return lit(json.dumps(x,separators=(',',':'),ensure_ascii=False))+'::jsonb'
def arr(xs):return 'array['+','.join(lit(x) for x in xs)+']::text[]'
# Full pg_proc JSON protects OID/owner/ACL/config plus all less-visible properties.
# Name-based body edges complement pg_depend, which omits PL/pgSQL runtime calls.
FUNCTIONS=f'''with recursive edges as (select p.oid caller,q.oid callee from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral regexp_matches(p.prosrc,'(private|public|attendance_admin_override_private|auth)\\.([a-zA-Z_][a-zA-Z_0-9]*)[[:space:]]*\\(','g') m join pg_namespace qn on qn.nspname=m[1] join pg_proc q on q.pronamespace=qn.oid and q.proname=m[2] where n.nspname in('private','public','attendance_admin_override_private','auth')), reachable(oid) as (select to_regprocedure(s)::oid from unnest({arr(CHANGED+['private.require_reauthentication_session()','private.has_company_feature(uuid,text)'])})s union select e.callee from reachable r join edges e on e.caller=r.oid) select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'metadata',to_jsonb(p),'definition',pg_get_functiondef(p.oid))order by p.oid),'[]') from pg_proc p where p.oid in(select oid from reachable) or p.oid in(select tgfoid from pg_trigger where tgrelid in(select to_regclass(s) from unnest({arr(TABLES)})s))'''
# Deliberately exclude planner statistics/relpages/relfrozenxid: no authorization meaning.
def table_query(names):
 return f'''select coalesce(jsonb_agg(jsonb_build_object('name',s,'relation',(select jsonb_build_object('oid',c.oid,'owner',c.relowner,'acl',c.relacl,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'kind',c.relkind,'options',c.reloptions,'persistence',c.relpersistence,'replica_identity',c.relreplident)from pg_class c where c.oid=to_regclass(s)), 'columns',(select jsonb_agg(to_jsonb(a)order by a.attnum)from pg_attribute a where a.attrelid=to_regclass(s)and a.attnum>0), 'defaults',(select jsonb_agg(to_jsonb(d)order by d.oid)from pg_attrdef d where d.adrelid=to_regclass(s)), 'constraints',(select jsonb_agg(to_jsonb(k)order by k.oid)from pg_constraint k where k.conrelid=to_regclass(s)), 'indexes',(select jsonb_agg(to_jsonb(i)order by i.indexrelid)from pg_index i where i.indrelid=to_regclass(s)), 'triggers',(select jsonb_agg(to_jsonb(t)order by t.oid)from pg_trigger t where t.tgrelid=to_regclass(s)), 'policies',(select jsonb_agg(to_jsonb(p)order by p.oid)from pg_policy p where p.polrelid=to_regclass(s)))order by s),'[]')from unnest({names})s'''
TABLE_QUERY=table_query(arr(TABLES))
DEPENDENCY_NAMES="array(select distinct n.nspname||'.'||c.relname from jsonb_array_elements(("+FUNCTIONS+"))f cross join lateral regexp_matches(f->'metadata'->>'prosrc','(private|public|auth)[.]([a-zA-Z_][a-zA-Z_0-9]*)','g')m join pg_namespace n on n.nspname=m[1]join pg_class c on c.relnamespace=n.oid and c.relname=m[2]where c.relkind in('r','p'))"
DEPENDENCY_QUERY=table_query(DEPENDENCY_NAMES)
CAPTURE=f'''select jsonb_build_object('functions',({FUNCTIONS}),'tables',({TABLE_QUERY}),'dependency_tables',({DEPENDENCY_QUERY}),'schemas',(select jsonb_agg(to_jsonb(n)order by oid)from pg_namespace n where nspname in('private','public','auth')),'default_acl',(select coalesce(jsonb_agg(to_jsonb(d)order by oid),'[]')from pg_default_acl d),'operator',current_user,'module_absent',to_regnamespace('document_adjustment_private') is null,'public_api_absent',not exists(select 1 from unnest({arr(PUBLIC_API)})s where to_regprocedure(s)is not null))snapshot;'''

def digest_block(before):
 if before:return """create temporary table adjustment_protected_rows(relation text primary key,n bigint,h text)on commit drop;
do $rows$ declare target text;n bigint;h text;begin foreach target in array """+arr(TABLES)+""" loop execute format($d$select count(*)::bigint,md5(coalesce(string_agg(h,''order by h),''))from(select md5(to_jsonb(x)::text)h from %s x)d$d$,target)into n,h;insert into pg_temp.adjustment_protected_rows values(target,n,h);end loop;end $rows$;"""
 return """do $rows$ declare r record;n bigint;h text;begin for r in select * from pg_temp.adjustment_protected_rows loop execute format($d$select count(*)::bigint,md5(coalesce(string_agg(h,''order by h),''))from(select md5(to_jsonb(x)::text)h from %s x)d$d$,r.relation)into n,h;if n is distinct from r.n or h is distinct from r.h then raise exception 'adjustment_business_rows_changed';end if;end loop;end $rows$;"""
def compose(s,body):
 if not s['module_absent'] or not s['public_api_absent'] or s['operator']!='postgres':raise ValueError('fresh module/API absent postgres snapshot required')
 # no component transactions; accept precisely one reviewed outer transaction
 if len(re.findall(r'^begin;\s*$',body,re.M))!=1 or len(re.findall(r'^commit;\s*$',body,re.M))!=1:raise ValueError('one source transaction required')
 body=re.sub(r'^(?:begin|commit);\s*$','',body,flags=re.M)
 out=["-- REVIEW ONLY. Root applies after exact-head CI and durable backup.",'begin;',"set local search_path='';set local lock_timeout='5s';set local statement_timeout='45s';",'lock table '+','.join(TABLES)+' in access exclusive mode;',"do $before$ begin if current_user<>'postgres' or session_user<>'postgres' then raise exception 'adjustment_operator';end if;if to_regnamespace('document_adjustment_private') is not null then raise exception 'adjustment_schema_exists';end if;"]
 out+=['if to_regprocedure('+lit(x)+") is not null then raise exception 'adjustment_api_exists';end if;" for x in PUBLIC_API]
 for f in s['functions']:
  out+=['if (select to_jsonb(p)from pg_proc p where p.oid=to_regprocedure('+lit(f['signature'])+')) is distinct from '+jl(f['metadata'])+" then raise exception 'adjustment_dependency_metadata_drift';end if;"]
 dependency_query=table_query(arr([t['name']for t in s['dependency_tables']]))
 out+=['if ('+dependency_query+')is distinct from '+jl(s['dependency_tables'])+" then raise exception 'adjustment_dependency_table_drift';end if;"]
 out+=['if ('+TABLE_QUERY+') is distinct from '+jl(s['tables'])+" then raise exception 'adjustment_table_catalogue_drift';end if;", "if (select jsonb_agg(to_jsonb(n)order by oid)from pg_namespace n where nspname in('private','public','auth'))is distinct from "+jl(s['schemas'])+" then raise exception 'adjustment_schema_acl_drift';end if;", "if (select coalesce(jsonb_agg(to_jsonb(d)order by oid),'[]')from pg_default_acl d)is distinct from "+jl(s['default_acl'])+" then raise exception 'adjustment_default_acl_drift';end if;end $before$;",digest_block(True),body]
 # Installation receipt belongs to this wrapper, no client/service access.
 out+=["create table document_adjustment_private.guarded_installation(singleton boolean primary key check(singleton),originals jsonb not null,installed_functions jsonb not null,installed_catalogue jsonb not null,installed_sequences jsonb not null,original_tables jsonb not null,original_schemas jsonb not null);alter table document_adjustment_private.guarded_installation enable row level security;revoke all on document_adjustment_private.guarded_installation from public,anon,authenticated,service_role;",
 "create function document_adjustment_private.guard_catalogue()returns jsonb language sql stable security definer set search_path='' as $cat$ select jsonb_build_object('schema',(select to_jsonb(n)from pg_namespace n where nspname='document_adjustment_private'),'relations',("+table_query("array(select n.nspname||'.'||c.relname from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='document_adjustment_private'and c.relkind in('r','p'))")+"),'external_tables',("+TABLE_QUERY+"),'dependency_tables',("+dependency_query+"),'sequences',(select jsonb_agg(to_jsonb(q)order by q.seqrelid)from pg_sequence q join pg_class c on c.oid=q.seqrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='document_adjustment_private'))$cat$;revoke all on function document_adjustment_private.guard_catalogue() from public,anon,authenticated,service_role;"]
 funcs="select coalesce(jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'metadata',to_jsonb(p))order by p.oid),'[]')from pg_proc p where p.pronamespace='document_adjustment_private'::regnamespace or p.oid in(select to_regprocedure(s)from unnest("+arr(CHANGED+PUBLIC_API)+")s)"
 seq="select coalesce(jsonb_agg(jsonb_build_object('name',schemaname||'.'||sequencename,'last_value',last_value)order by sequencename),'[]')from pg_sequences where schemaname='document_adjustment_private'"
 out+=['insert into document_adjustment_private.guarded_installation values(true,'+jl(s['functions'])+',('+funcs+'),document_adjustment_private.guard_catalogue(),('+seq+'),'+jl(s['tables'])+','+jl(s['schemas'])+');',"do $off$ declare n text;begin if exists(select 1 from document_adjustment_private.rollout)then raise exception 'adjustment_not_unused_off';end if;foreach n in array array['templates','template_versions','scope_versions','occurrences','commands','audit','previews']loop if exists(select 1 from pg_class c join pg_namespace ns on ns.oid=c.relnamespace where ns.nspname='document_adjustment_private'and c.relname=n)then execute format('select exists(select 1 from document_adjustment_private.%I)',n)into strict "+'dummy' +";end if;end loop;end $off$;"]
 # replace block with correct generic empty check
 out[-1]="do $off$ declare n text;used boolean;f jsonb;p jsonb;begin for n in select c.relname from pg_class c where c.relnamespace='document_adjustment_private'::regnamespace and c.relkind in('r','p')and c.relname<>'guarded_installation'loop execute format('select exists(select 1 from document_adjustment_private.%I)',n)into used;if used then raise exception 'adjustment_not_unused_off';end if;end loop;for f in select value from jsonb_array_elements("+jl(s['functions'])+")loop select to_jsonb(x)into p from pg_proc x where x.oid=to_regprocedure(f->>'signature');if (f->>'signature')=any("+arr(CHANGED)+")then if p-'prosrc' is distinct from (f->'metadata')-'prosrc' then raise exception 'adjustment_original_metadata_changed';end if;elsif p is distinct from f->'metadata' then raise exception 'adjustment_dependency_changed';end if;end loop;end $off$;"
 out += ["do $access_after$ begin if exists(select 1 from pg_proc p cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a where (p.pronamespace='document_adjustment_private'::regnamespace or p.oid in(select to_regprocedure(x)from unnest("+arr(PUBLIC_API)+")x))and a.grantee<>p.proowner and not(p.oid in(select to_regprocedure(x)from unnest("+arr(PUBLIC_API)+")x)and a.grantee='authenticated'::regrole and a.privilege_type='EXECUTE'and not a.is_grantable))then raise exception 'adjustment_new_function_acl';end if;if exists(select 1 from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S'then 's'::\"char\"else 'r'::\"char\"end,c.relowner)))a where c.relnamespace='document_adjustment_private'::regnamespace and a.grantee<>c.relowner)then raise exception 'adjustment_new_relation_acl';end if;if has_schema_privilege('service_role','document_adjustment_private','USAGE')or has_schema_privilege('anon','document_adjustment_private','USAGE')or has_schema_privilege('authenticated','document_adjustment_private','USAGE')then raise exception 'adjustment_new_schema_acl';end if;end $access_after$;"]
 out += ["do $catalogue_after$ declare actual jsonb;begin select jsonb_agg(jsonb_set(t,'{triggers}',coalesce((select jsonb_agg(v order by (v->>'oid')::oid)from jsonb_array_elements(coalesce(nullif(t->'triggers','null'::jsonb),'[]'::jsonb))v where v->>'tgname'not in('document_adjustments_finalize_invoice','document_adjustments_finalize_certificate')and not exists(select 1 from pg_constraint fk where fk.oid=(v->>'tgconstraint')::oid and fk.connamespace='document_adjustment_private'::regnamespace)),'null'::jsonb))order by t->>'name')into actual from jsonb_array_elements(("+dependency_query+"))t;if actual is distinct from "+jl(s['dependency_tables'])+" then raise exception 'adjustment_unexpected_business_catalogue_change';end if;end $catalogue_after$;"]
 out += ["do $catalogue_after$ declare actual jsonb;begin select jsonb_agg(jsonb_set(t,'{triggers}',coalesce((select jsonb_agg(v order by (v->>'oid')::oid)from jsonb_array_elements(coalesce(nullif(t->'triggers','null'::jsonb),'[]'::jsonb))v where v->>'tgname'not in('document_adjustments_finalize_invoice','document_adjustments_finalize_certificate')and not exists(select 1 from pg_constraint fk where fk.oid=(v->>'tgconstraint')::oid and fk.connamespace='document_adjustment_private'::regnamespace)),'null'::jsonb))order by t->>'name')into actual from jsonb_array_elements(("+TABLE_QUERY+"))t;if actual is distinct from "+jl(s['tables'])+" then raise exception 'adjustment_unexpected_business_catalogue_change';end if;end $catalogue_after$;",digest_block(False),'commit;']
 # restore calls guard before dropping anything, restores every original declaration (only four changed).
 restore=['-- REVIEW ONLY. UNUSED RESTORE; refuses any ledger/configuration/activity.','begin;',"set local search_path='';set local lock_timeout='5s';set local statement_timeout='45s';",'lock table '+','.join(TABLES)+' in access exclusive mode;',"lock table document_adjustment_private.rollout,document_adjustment_private.templates,document_adjustment_private.template_versions,document_adjustment_private.scope_versions,document_adjustment_private.occurrences,document_adjustment_private.commands,document_adjustment_private.audit,document_adjustment_private.previews,document_adjustment_private.guarded_installation in access exclusive mode;",digest_block(True),"do $restore$ declare r document_adjustment_private.guarded_installation%rowtype;f jsonb;n text;used boolean;begin if current_user<>'postgres'or session_user<>'postgres'then raise exception 'adjustment_operator';end if;select * into strict r from document_adjustment_private.guarded_installation;if (select jsonb_agg(to_jsonb(n)order by oid)from pg_namespace n where nspname in('private','public','auth'))is distinct from r.original_schemas then raise exception 'adjustment_original_schema_acl_changed';end if;if exists(select 1 from pg_proc p where p.pronamespace<>'document_adjustment_private'::regnamespace and p.oid not in(select to_regprocedure(x)from unnest("+arr(CHANGED+PUBLIC_API)+")x)and p.prosrc~*'document_adjustment_private[.]')then raise exception 'adjustment_external_runtime_dependency';end if;if document_adjustment_private.guard_catalogue()is distinct from r.installed_catalogue or ("+funcs+")is distinct from r.installed_functions or ("+seq+")is distinct from r.installed_sequences then raise exception 'adjustment_installed_catalogue_changed';end if;for n in select c.relname from pg_class c where c.relnamespace='document_adjustment_private'::regnamespace and c.relkind in('r','p')and c.relname<>'guarded_installation'loop execute format('select exists(select 1 from document_adjustment_private.%I)',n)into used;if used then raise exception 'adjustment_used_restore_refused';end if;end loop;for f in select value from jsonb_array_elements(r.originals)loop if f->>'signature'=any("+arr(CHANGED)+")then execute f->>'definition';end if;end loop;for f in select value from jsonb_array_elements(r.originals)loop if(select to_jsonb(p)from pg_proc p where p.oid=to_regprocedure(f->>'signature'))is distinct from f->'metadata'then raise exception 'adjustment_original_restore_failed';end if;end loop;end $restore$;",'drop trigger document_adjustments_finalize_invoice on public.invoices;drop trigger document_adjustments_finalize_certificate on public.payment_certificates;']
 # reverse dependency teardown of public APIs, then helper graph via repeated RESTRICT.
 restore += ['drop function '+x+';' for x in reversed(PUBLIC_API)]
 restore += ["do $drop_helpers$ declare f record;progress boolean;remaining int;begin loop progress:=false;for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='document_adjustment_private'::regnamespace and p.prorettype<>'trigger'::regtype loop begin execute 'drop function '||f.signature||' restrict';progress:=true;exception when dependent_objects_still_exist then null;end;end loop;select count(*)into remaining from pg_proc where pronamespace='document_adjustment_private'::regnamespace and prorettype<>'trigger'::regtype;exit when remaining=0;if not progress then raise exception 'adjustment_unknown_function_dependency';end if;end loop;end $drop_helpers$;","do $drop_tables$ declare t record;progress boolean;remaining int;begin loop progress:=false;for t in select c.oid::regclass::text relation from pg_class c where c.relnamespace='document_adjustment_private'::regnamespace and c.relkind in('r','p')loop begin execute 'drop table '||t.relation||' restrict';progress:=true;exception when dependent_objects_still_exist then null;end;end loop;select count(*)into remaining from pg_class where relnamespace='document_adjustment_private'::regnamespace and relkind in('r','p');exit when remaining=0;if not progress then raise exception 'adjustment_unknown_table_dependency';end if;end loop;end $drop_tables$;","do $drop_triggers$ declare f record;begin for f in select p.oid::regprocedure::text signature from pg_proc p where p.pronamespace='document_adjustment_private'::regnamespace loop execute 'drop function '||f.signature||' restrict';end loop;end $drop_triggers$;",'drop schema document_adjustment_private restrict;','do $restored_catalogue$ begin if ('+TABLE_QUERY+')is distinct from '+jl(s['tables'])+" then raise exception 'adjustment_original_tables_not_restored';end if;end $restored_catalogue$;",'do $dependency_restored$ begin if ('+dependency_query+')is distinct from '+jl(s['dependency_tables'])+" then raise exception 'adjustment_dependency_tables_not_restored';end if;end $dependency_restored$;",digest_block(False),'commit;']
 return '\n'.join(out)+'\n','\n'.join(restore)+'\n'
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('--snapshot');p.add_argument('--body');a=p.parse_args()
 (ROOT/'capture.sql').write_text(CAPTURE)
 if a.snapshot:
  s=json.loads(Path(a.snapshot).read_text());s=s.get('snapshot',s) if isinstance(s,dict)else s[0]['snapshot']
  install,restore=compose(s,Path(a.body).read_text());(ROOT/'install-off.guarded.sql.review-only').write_text(install);(ROOT/'restore-unused.guarded.sql.review-only').write_text(restore)
  (ROOT/'manifest.json').write_text(json.dumps({'input_sha256':hashlib.sha256(Path(a.body).read_bytes()).hexdigest(),'snapshot_sha256':hashlib.sha256(Path(a.snapshot).read_bytes()).hexdigest(),'function_count':len(s['functions']),'locked_business_tables':len(TABLES),'dependency_tables':len(s['dependency_tables']),'install_sha256':hashlib.sha256(install.encode()).hexdigest(),'restore_sha256':hashlib.sha256(restore.encode()).hexdigest(),'production_applied':False},indent=2))
  print(json.dumps({'functions':len(s['functions']),'install_sha256':hashlib.sha256(install.encode()).hexdigest(),'restore_sha256':hashlib.sha256(restore.encode()).hexdigest()}))
